            --panel-bg-color: #2c2c2e;
            --border-color: #444;
            --text-color: #e0e0e0;
            --text-dim-color: #9a9a9a;
            --header-color: #E5B84B;
            --highlight-color: #E5B84B;
            --positive-color: #61afef;
