                } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                    html += `<div class="stat-value sub-grid">${renderGenericObject(value)}</div>`;
                } else {
                    html += `<div class="stat-value">${Array.isArray(value) ? value.join(', ') || '无' : value}</div>`;
