            try {
                // Tab 1: 核心
                document.getElementById('tab-core').innerHTML = `<div class="grid-container"><div class="card"><div class="card-header">🌍 世界信息</div>${renderGenericObject(stat['世界信息'])}</div><div class="card"><div class="card-header">🎭 互动场景</div>${renderGenericObject(stat['互动场景状态'])}</div></div>`;

                // Tab 2: USER
                const user = stat['user专属状态'] || {};
                document.getElementById('tab-user').innerHTML = `<div class="grid-container"><div class="card"><div class="card-header">📊 核心属性</div><div class="stat-grid">${renderProgressBar('体力', user.体力?.当前体力, user.体力?.体力上限, 'var(--positive-color)')}${renderProgressBar('先天炁气(精液)', user.能量?.['先天炁气(精液)']?.数量, user.能量?.['先天炁气(精液)']?.上限, 'var(--text-color)')}${renderProgressBar('混沌灵气', user.能量?.混沌灵气?.数量, user.能量?.混沌灵气?.上限, 'var(--highlight-color)')}</div></div><div class="card"><div class="card-header">🛡️ 装备 & 效果</div>${renderGenericObject(user['装备'])}<div class="sub-header">当前效果</div><div>${(user['当前效果'] || []).join(', ') || '<span class="empty-placeholder">无</span>'}</div></div><div class="card" style="grid-column: 1 / -1;"><div class="card-header">🌟 天赋与技能</div>${renderGenericObject(user['天赋与技能'])}</div></div>`;

                // Tab 3: 角色
                const characters = stat['角色列表'] || {};
                document.getElementById('tab-characters').innerHTML = Object.keys(characters).length > 0 ? Object.values(characters).map(char => `<details class="card"><summary>👤 ${char.基础信息?.姓名 || '未知角色'}</summary><div class="panel-content"><div class="grid-container"><div><div class="sub-header">基础信息</div>${renderGenericObject(char['基础信息'])}</div><div><div class="sub-header">外貌</div>${renderGenericObject(char['外貌'])}</div><div><div class="sub-header">生理</div>${renderGenericObject(char['生理'])}</div><div><div class="sub-header">状态</div><div class="stat-grid">${renderProgressBar('体力', char.状态?.当前体力, char.状态?.体力上限, 'var(--positive-color)')}<div class="stat-label">好感度</div><div class="stat-value">${char.状态?.好感度}</div><div class="stat-label">欲望度</div><div class="stat-value">${char.状态?.欲望度}</div><div class="stat-label">尸化度</div><div class="stat-value text-negative">${char.状态?.尸化度}</div><div class="stat-label">高潮度</div><div class="stat-value">${char.状态?.高潮度}</div></div><div class="sub-header">能量</div><div class="stat-grid">${renderProgressBar('本源煞气', char.能量?.本源煞气?.数量, char.能量?.本源煞气?.上限, 'var(--negative-color)')}${renderProgressBar('先天炁气', char.能量?.先天炁气?.数量, char.能量?.先天炁气?.上限, 'var(--text-color)')}${renderProgressBar('混沌灵气', char.能量?.混沌灵气?.数量, char.能量?.混沌灵气?.上限, 'var(--highlight-color)')}</div></div></div></div></details>`).join('') : '<div class="empty-placeholder">暂无角色信息</div>';

                // Tab 4: 太虚链
                document.getElementById('tab-base').innerHTML = `<div class="card">${renderGenericObject(stat['太虚链系统'])}</div>`;

                // Tab 5: 世界
                document.getElementById('tab-world').innerHTML = `<div class="grid-container"><div class="card"><div class="card-header">🗺️ 地图系统</div>${renderGenericObject(stat['地图系统'])}</div><div class="card"><div class="card-header">🏆 成就与记忆</div>${renderGenericObject(stat['成就与记忆'])}</div></div>`;

            } catch (error) {
                console.error('[ERA Status] Error rendering dashboard:', error);
                // 仅清空内容，避免破坏框架
                document.querySelectorAll('.tab-pane').forEach(p => p.innerHTML = `<div style="color: var(--negative-color); padding: 20px;">渲染引擎出现致命错误: ${error.message}</div>`);
            }
        }

        const loader = document.getElementById('loader');
        eventOn('era:writeDone', (detail) => {
