                // Tab 3: 角色
                const characters = stat['角色列表'] || {};
                document.getElementById('tab-characters').innerHTML = Object.keys(characters).length > 0 ? Object.values(characters).map(char => `<details class="card"><summary>👤 ${char.基础信息?.姓名 || '未知角色'}</summary><div class="panel-content"><div class="grid-container"><div><div class="sub-header">基础信息</div>${renderGenericObject(char['基础信息'])}</div><div><div class="sub-header">外貌</div>${renderGenericObject(char['外貌'])}</div><div><div class="sub-header">生理</div>${renderGenericObject(char['生理'])}</div><div><div class="sub-header">状态</div><div class="stat-grid">${renderProgressBar('体力', char.状态?.当前体力, char.状态?.体力上限, 'var(--positive-color)')}<div class="stat-label">好感度</div><div class="stat-value">${char.状态?.好感度}</div><div class="stat-label">欲望度</div><div class="stat-value">${char.状态?.欲望度}</div><div class="stat-label">尸化度</div><div class="stat-value text-negative">${char.状态?.尸化度}</div><div class="stat-label">高潮度</div><div class="stat-value">${char.状态?.高潮度}</div></div><div class="sub-header">能量</div><div class="stat-grid">${renderProgressBar('本源煞气', char.能量?.本源煞气?.数量, char.能量?.本源煞气?.上限, 'var(--negative-color)')}${renderProgressBar('先天炁气', char.能量?.先天炁气?.数量, char.能量?.先天炁气?.上限, 'var(--text-color)')}${renderProgressBar('混沌灵气', char.能量?.混沌灵气?.数量, char.能量?.混沌灵气?.上限, 'var(--highlight-color)')}</div></div></div></div></details>`).join('') : '<div class="empty-placeholder">暂无角色信息</div>';

